const salida = [];
const respuestas = $input.all();
const entradas = $('Limpiar texto').all();

for (let i = 0; i < respuestas.length; i++) {
  const correo = (entradas[i] && entradas[i].json.correo) || {};
  const respuesta = respuestas[i].json;

  const texto = respuesta.choices?.[0]?.message?.content || '';

  let datos = {};
  let error_ia = false;
  let motivo = '';
  if (respuesta.error) {
    error_ia = true;
    const detalle = typeof respuesta.error === 'string' ? respuesta.error : (respuesta.error.message || JSON.stringify(respuesta.error));
    motivo = ('Error de la IA: ' + detalle).slice(0, 300);
  } else {
    try {
      const m = texto.match(/\{[\s\S]*\}/);
      datos = JSON.parse(m ? m[0] : texto);
    } catch (e) {
      error_ia = true;
      motivo = 'No se pudo leer la respuesta de la IA';
    }
  }

  const categoria = String(datos.categoria || 'NO_ENTENDIDO').toUpperCase();
  const esReserva = ['RESERVA', 'MODIFICACION'].includes(categoria);
  const pax = datos.pax || {};
  const clientes = esReserva && Array.isArray(datos.clientes) ? datos.clientes.join(', ') : '';
  const servicios = esReserva && Array.isArray(datos.servicios) && datos.servicios.length > 0
    ? datos.servicios
    : [{}];

  let estado;
  if (categoria === 'PUBLICIDAD' || categoria === 'OTRO') {
    estado = 'sin accion';
  } else if (esReserva) {
    const primero = servicios[0] || {};
    estado = (primero.fecha_servicio || primero.hotel) ? 'pendiente de transcribir' : 'revisar';
  } else {
    estado = 'revisar';
  }

  const base = {
    categoria: categoria,
    remitente: correo.from || '',
    asunto: correo.subject || '',
    estado: estado,
    fecha: correo.date || '',
    cuerpo: correo.textPlain || '',
    message_id: correo.metadata?.['message-id'] || '',
    buzon: correo.buzon || 'serviciosintegraleskaizen.ia@gmail.com',
    agencia: esReserva ? (datos.agencia || '') : '',
    nombre_cliente: clientes,
    telefono: datos.telefono || '',
    adultos: esReserva ? (Number(pax.adultos) || 0) : 0,
    ninos: esReserva ? (Number(pax.ninos) || 0) : 0,
    infantes: esReserva ? (Number(pax.infantes) || 0) : 0,
    error_ia: error_ia,
    motivo: motivo
  };

  servicios.forEach((s, n) => {
    salida.push({
      json: {
        ...base,
        numero_servicio: n + 1,
        tipo_servicio: s.tipo_servicio || '',
        actividad: s.actividad || '',
        aeropuerto: s.aeropuerto || datos.aeropuerto || '',
        fecha_servicio: s.fecha_servicio || '',
        hora_servicio: s.hora_servicio || '',
        vuelo: s.vuelo || '',
        hotel: s.hotel || '',
        punto_partida: s.punto_partida || '',
        punto_llegada: s.punto_llegada || ''
      }
    });
  });
}

return salida;

// Modelo de IA en OpenRouter. Copia el ID exacto desde openrouter.ai/models.
const MODELO = "anthropic/claude-haiku-5.5";

const correos = $('Traducir correo').all().map(x => x.json);

return $input.all().map(item => {
  const correo = correos.find(c => c.metadata['message-id'] === item.json.message_id) || {};
  const dominio = ((correo.from || '').match(/@([^>\s]+)/) || [])[1] || '';
  const recibido = new Date(correo.date);
  const fechaRecibido = isNaN(recibido) ? '' : recibido.toISOString().slice(0, 10);
  const instruccion = `Clasifica este correo en una categoria: RESERVA, MODIFICACION, SEGUIMIENTO, CONSULTA, PUBLICIDAD, FACTURA, OTRO, NO_ENTENDIDO. RESERVA es una solicitud de servicio nueva. MODIFICACION es un cambio a una reserva ya enviada (cambiar fecha, hora, hotel, pasajeros o cancelar). Cadenas de correos (RE:, RV:, Fwd:, Reenviado): el mensaje mas reciente esta arriba y los anteriores debajo, despues de lineas como De:, From:, Enviado:, Asunto: o Forwarded message; el pedido original de la agencia suele estar al final. Lee toda la cadena antes de decidir. Si alguien reenvia un pedido de reserva (por ejemplo Somos Viaje reenviando el correo de una agencia), es RESERVA con los datos del pedido original. Si el mensaje mas reciente pide un cambio sobre una reserva de la cadena, es MODIFICACION: llena todos los datos de la reserva con los valores nuevos y toma de la cadena los que no cambian. Si el mensaje mas reciente solo agradece, confirma o pregunta algo sin datos nuevos, es SEGUIMIENTO. Si el asunto empieza con Leido:, Leído:, Read: o Lu:, es un aviso automatico de que alguien leyo un correo (acuse de lectura): categoria OTRO, aunque el asunto diga reserva. El asunto suele traer el nombre del pasajero y la cantidad de pax (por ejemplo PAX MEDINA JUAN X 09 son 9 pasajeros a nombre de Medina Juan): usalo junto con el cuerpo. Devuelve solo JSON valido, sin texto extra. Formato: {"categoria": "...", "agencia": "...", "clientes": [], "telefono": "", "pax": {"adultos": 0, "ninos": 0, "infantes": 0}, "aeropuerto": "", "servicios": []}. Regla: si la categoria es RESERVA o MODIFICACION, llena agencia, clientes, pax, aeropuerto y servicios con los datos del correo (en MODIFICACION usa los datos nuevos). Para agencia: escribe SOLO el nombre de la empresa de viajes. Nunca pongas el nombre de una persona ni el nombre del remitente. Busca el nombre de la empresa en la firma o el pie de pagina escritos; si el dominio no es gmail, hotmail, yahoo, outlook ni de Somos Viaje, puedes usarlo. Si no encuentras el nombre de la empresa, deja agencia vacia. Somos Viaje (somosviajepuntacana.com, somosviajeorlando.com) es la empresa que RECIBE los correos: nunca pongas Somos Viaje como agencia; si el correo es una respuesta o reenvio de Somos Viaje, busca la agencia en el mensaje original. Ignora banners y anuncios de publicidad (excursiones, parques, paquetes) al buscar la agencia. Para telefono: escribe el numero de contacto del pasajero o cliente (el que viaja o el contacto para el traslado), con codigo de pais si aparece, por ejemplo +593939601335. Si hay varios, separalos con coma. Nunca pongas telefonos de Somos Viaje (+18493622139, +18097957625) ni los telefonos de la firma de la agencia o de la persona que escribe; si no hay telefono del pasajero, deja telefono vacio. Si la categoria es otra, deja agencia en blanco, clientes vacio, telefono vacio, pax en 0 y servicios vacio. Para RESERVA y MODIFICACION llena servicios con tipo_servicio, actividad, aeropuerto, hora_servicio, fecha_servicio, vuelo, hotel, punto_partida, punto_llegada. Formatos obligatorios: fecha_servicio en AAAA-MM-DD (si el correo no trae el año, usa el año de la fecha de recibido, o el siguiente si esa fecha ya paso; en hotel usa la fecha de entrada); hora_servicio en HH:MM de 24 horas; aeropuerto en codigo IATA de 3 letras (PUJ, SDQ, LRM, POP, STI) solo si el correo lo dice. Si hay hotel o fechas en el texto, llenalos dentro de servicios aunque el servicio no tenga actividad. Ignora el bloque de Vision general creada por IA y los textos de firma o confidencialidad. Si la informacion de vuelos esta solo en una imagen, deja vuelo vacio. Responde directamente con el JSON, sin razonar en voz alta. Fecha de recibido: ${fechaRecibido}. Dominio del remitente: ${dominio}. Asunto: ${String(correo.subject || '').replace(/\s+/g, ' ')}. Correo: `;
  // Se quitan imágenes [cid:...] y enlaces largos de firmas para que la IA vea el correo y el mensaje original.
  const limpio = String(correo.textPlain || '')
    .replace(/\[cid:[^\]]*\]/g, ' ')
    .replace(/<(?:https?:|mailto:)[^>]*>/g, ' ')
    .replace(/\[https?:[^\]]*\]/g, ' ')
    .replace(/https?:\/\/\S{80,}/g, ' ')
    .replace(/\[(?:Facebook|LinkedIn|Instagram|YouTube|Tiktok|TikTok|Twitter|WhatsApp)\]/gi, ' ')
    .replace(/\s+/g, ' ');
  // En cadenas largas el pedido original queda al final: se manda el principio y el final.
  const texto = limpio.length > 12000 ? limpio.slice(0, 6000) + ' [...] ' + limpio.slice(-6000) : limpio;
  return {
    json: {
      body: {
        model: MODELO,
        max_tokens: 4000,
        messages: [{ role: "user", content: instruccion + texto }]
      },
      dominio: dominio,
      correo: correo
    }
  };
});

// Arregla tildes dañadas que mandan algunos sistemas (BÃ¡varo -> Bávaro).
const MALAS = { 'Ã¡': 'á', 'Ã©': 'é', 'Ã­': 'í', 'Ã³': 'ó', 'Ãº': 'ú', 'Ã±': 'ñ', 'Ã‘': 'Ñ', 'Ã‰': 'É', 'Ã“': 'Ó', 'Ãš': 'Ú', 'Ã¼': 'ü', 'â€¢': '•', 'â€“': '–', 'â€œ': '"', 'â€\x9d': '"' };

function decodificar(s) {
  return String(s || '')
    .replace(/Ã[¡©­³º±‘‰“š¼]|â€[¢“œ\x9d]/g, m => MALAS[m] || m)
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&#x27;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function textoPlano(parte) {
  if (!parte) return '';
  if (parte.mimeType === 'text/plain' && parte.body && parte.body.data) {
    return Buffer.from(parte.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
  }
  for (const p of (parte.parts || [])) {
    const t = textoPlano(p);
    if (t) return t;
  }
  return '';
}

function htmlATexto(html) {
  return String(html || '')
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
}

// Gmail llega un correo por elemento; Microsoft 365 llega como una lista en "value".
const BUZON_GMAIL = 'serviciosintegraleskaizen.ia@gmail.com';
const BUZON_MICROSOFT = 'operaciones@somosviajepuntacana.com';
const entradas = $('Juntar correos').all().flatMap(item => Array.isArray(item.json.value)
  ? item.json.value.map(m => ({ json: m, buzon: BUZON_MICROSOFT }))
  : [{ json: item.json, buzon: BUZON_GMAIL }]);

const leidos = entradas.filter(item => item.json.id).map(item => {
  const j = item.json;
  if (j.receivedDateTime) {
    const de = (j.from && j.from.emailAddress) || {};
    const cuerpo = (j.body && j.body.content) || '';
    return {
      json: {
        metadata: { 'message-id': j.id },
        buzon: item.buzon,
        from: decodificar(de.name ? `${de.name} <${de.address}>` : (de.address || '')),
        subject: decodificar(j.subject || ''),
        date: j.receivedDateTime,
        textPlain: decodificar(j.body && j.body.contentType === 'html' ? htmlATexto(cuerpo) : cuerpo)
      }
    };
  }
  const cabeceras = (j.payload && j.payload.headers) || [];
  const leer = (nombre) => {
    const h = cabeceras.find(x => x.name && x.name.toLowerCase() === nombre.toLowerCase());
    if (h) return h.value;
    const directo = j[nombre] || j[nombre.toLowerCase()];
    if (directo && typeof directo === 'object') return directo.text || '';
    return directo || '';
  };
  const fecha = leer('Date') || (j.internalDate ? new Date(Number(j.internalDate)).toISOString() : '');
  const texto = j.text || textoPlano(j.payload) || htmlATexto(j.html) || j.snippet || '';
  return {
    json: {
      metadata: { 'message-id': j.id },
      buzon: item.buzon,
      from: decodificar(leer('From')),
      subject: decodificar(leer('Subject')),
      date: fecha,
      textPlain: decodificar(texto)
    }
  };
});

// Correos que fallaron antes (vienen del nodo "Reintentar fallidos"), aunque ya no estén en las fechas que se leen.
const reintentos = $input.all().map(x => x.json).filter(j => j.reintento && j.message_id).map(j => ({
  json: {
    metadata: { 'message-id': j.message_id },
    buzon: j.buzon || BUZON_GMAIL,
    from: j.remitente || '',
    subject: j.asunto || '',
    date: j.fecha || '',
    textPlain: j.cuerpo || ''
  }
}));

// Si un correo llega por los dos caminos, se usa una sola vez (el recién leído tiene el texto más completo).
const vistos = new Set();
return [...leidos, ...reintentos].filter(x => {
  const id = x.json.metadata['message-id'];
  if (vistos.has(id)) return false;
  vistos.add(id);
  return true;
});
